@sig trait Battery_Evidence_Qualification_Api {
  def id: Art.BridgeId
  def battery_sample_Id : Art.PortId
  def evidence_to_owner_Id : Art.PortId
  def evidence_to_attention_Id : Art.PortId
  def evidence_to_readiness_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var evidence_to_owner: Drone_Battery_Charge_Supervisor.BatteryEvidence.Type = $

  def put_evidence_to_owner(value : Drone_Battery_Charge_Supervisor.BatteryEvidence.Type) : Unit = {
    Contract(
      Modifies(evidence_to_owner),
      Ensures(
        evidence_to_owner == value
      )
    )
    Spec {
      evidence_to_owner = value
    }

    Art.putValue(evidence_to_owner_Id, Drone_Battery_Charge_Supervisor.BatteryEvidence_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var evidence_to_attention: Drone_Battery_Charge_Supervisor.BatteryEvidence.Type = $

  def put_evidence_to_attention(value : Drone_Battery_Charge_Supervisor.BatteryEvidence.Type) : Unit = {
    Contract(
      Modifies(evidence_to_attention),
      Ensures(
        evidence_to_attention == value
      )
    )
    Spec {
      evidence_to_attention = value
    }

    Art.putValue(evidence_to_attention_Id, Drone_Battery_Charge_Supervisor.BatteryEvidence_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var evidence_to_readiness: Drone_Battery_Charge_Supervisor.BatteryEvidence.Type = $

  def put_evidence_to_readiness(value : Drone_Battery_Charge_Supervisor.BatteryEvidence.Type) : Unit = {
    Contract(
      Modifies(evidence_to_readiness),
      Ensures(
        evidence_to_readiness == value
      )
    )
    Spec {
      evidence_to_readiness = value
    }

    Art.putValue(evidence_to_readiness_Id, Drone_Battery_Charge_Supervisor.BatteryEvidence_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Battery_Evidence_Qualification_Initialization_Api (
  val id: Art.BridgeId,
  val battery_sample_Id : Art.PortId,
  val evidence_to_owner_Id : Art.PortId,
  val evidence_to_attention_Id : Art.PortId,
  val evidence_to_readiness_Id : Art.PortId) extends Battery_Evidence_Qualification_Api

@datatype class Battery_Evidence_Qualification_Operational_Api (
  val id: Art.BridgeId,
  val battery_sample_Id : Art.PortId,
  val evidence_to_owner_Id : Art.PortId,
  val evidence_to_attention_Id : Art.PortId,
  val evidence_to_readiness_Id : Art.PortId) extends Battery_Evidence_Qualification_Api {

  // Logika spec var representing port state for incoming data port
  @spec var battery_sample: Drone_Battery_Charge_Supervisor.BatterySample = $

  def get_battery_sample() : Option[Drone_Battery_Charge_Supervisor.BatterySample] = {
    Contract(
      Ensures(
        Res == Some(battery_sample)
      )
    )
    val value : Option[Drone_Battery_Charge_Supervisor.BatterySample] = Art.getValue(battery_sample_Id) match {
      case Some(Drone_Battery_Charge_Supervisor.BatterySample_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port battery_sample.  Expecting 'Drone_Battery_Charge_Supervisor.BatterySample_Payload' but received ${v}")
        None[Drone_Battery_Charge_Supervisor.BatterySample]()
      case _ => None[Drone_Battery_Charge_Supervisor.BatterySample]()
    }
    return value
  }
}
